class Counter {
    int value;
public:
    Counter(int v = 0) : value(v) {}

    Counter &operator++() {            // prefix  ++c
        ++value;
        return *this;
    }
    Counter operator++(int) {          // postfix c++
        Counter old = *this;
        ++value;
        return old;
    }
    int get() const { return value; }
};

int main() {
    Counter c(5);
    cout << "Start: " << c.get() << endl;
    cout << "++c gives " << (++c).get() << endl;
    cout << "c++ gives " << (c++).get() << endl;
    cout << "Now: " << c.get() << endl;
    return 0;
}

