#include <iostream>
#include <stdexcept>
#include <string>
using namespace std;

class InsufficientFunds : public runtime_error {
public:
    InsufficientFunds(double needed)
        : runtime_error("Insufficient funds: need " + to_string(needed) + " more") {}
};

class Account {
    double balance;
public:
    Account(double b) : balance(b) {}
    void withdraw(double amount) {
        if (amount <= 0) throw invalid_argument("Amount must be positive");
        if (amount > balance) throw InsufficientFunds(amount - balance);
        balance -= amount;
    }
    double get() const { return balance; }
};

int main() {
    Account acc(100);
    double attempts[] = {30, -5, 500};
    for (double amount : attempts) {
        try {
            acc.withdraw(amount);
            cout << "Withdrew " << amount << ", balance " << acc.get() << endl;
        } catch (const invalid_argument &e) {
            cout << "Bad input: " << e.what() << endl;
        } catch (const InsufficientFunds &e) {
            cout << e.what() << endl;
        }
    }
    return 0;
}

