    {
        ofstream log("log.txt");                      // start fresh
        log << "start" << endl;
    }
    {
        ofstream log("log.txt", ios::app);            // ios::app = append
        log << "second entry" << endl;
        log << "third entry" << endl;
    }

    ifstream in("log.txt");
    string word;
    int words = 0;
    while (in >> word) words++;                       // >> reads word by word
